// Loads docs/specs/test-vectors/*.json and runs them against THIS
// from-scratch Node.js implementation (canonicalize.mjs + jws.mjs),
// built only from docs/specs/jws-artifact-signatures.md. No import of
// any AIMO Python package. Proves Python -> Node.js interoperability
// for the vectors generated by the Python reference implementation.

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { canonicalize } from "./canonicalize.mjs";
import { digestHex, publicKeyFromJwk, verifyJws, JwsVerificationError } from "./jws.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const VECTORS_DIR = join(HERE, "..");

function loadVector(name) {
  return JSON.parse(readFileSync(join(VECTORS_DIR, name), "utf8"));
}

function resolverFor(vector) {
  const key = publicKeyFromJwk(vector.public_key_jwk);
  return (organizationId, kid) => {
    if (organizationId === vector.signer_organization_id && kid === vector.kid) return key;
    return null;
  };
}

function withoutProof(artifact) {
  const { proof, ...rest } = artifact;
  return rest;
}

function verifyArtifactProof(artifact, vector) {
  const proof = artifact.proof;
  if (!proof || !proof.jws) throw new JwsVerificationError("Artifact carries no proof.");
  const claims = verifyJws(proof.jws, {
    resolvePublicKey: resolverFor(vector),
    expectedAudience: vector.expected_recipient_organization_id,
  });
  const stripped = withoutProof(artifact);
  const { hex } = digestHex(stripped);
  if (hex !== claims.artifact_digest) {
    throw new JwsVerificationError("Signed digest does not match the artifact's actual content.");
  }
  if (
    claims.neg !== artifact.transaction_id ||
    claims.typ !== artifact.type ||
    claims.hash !== (artifact.content_hash ?? null) ||
    claims.ver !== artifact.version
  ) {
    throw new JwsVerificationError("Signed claims do not match this artifact.");
  }
  return claims;
}

let failures = 0;
function check(name, fn) {
  try {
    fn();
    console.log(`PASS  ${name}`);
  } catch (exc) {
    failures += 1;
    console.error(`FAIL  ${name}: ${exc.message}`);
  }
}

// vector_01: verify-success
check("vector_01_valid_signature (verify-success)", () => {
  const vector = loadVector("vector_01_valid_signature.json");
  const artifact = vector.signed_artifact;
  const stripped = withoutProof(artifact);
  const canon = canonicalize(stripped);
  if (canon !== vector.expected_canonicalized_artifact_without_proof) {
    throw new Error(`canonical form mismatch:\n  got:      ${canon}\n  expected: ${vector.expected_canonicalized_artifact_without_proof}`);
  }
  const { hex } = digestHex(stripped);
  if (hex !== vector.expected_artifact_digest) {
    throw new Error(`digest mismatch: got ${hex}, expected ${vector.expected_artifact_digest}`);
  }
  const claims = verifyArtifactProof(artifact, vector);
  const expected = vector.expected_verified_claims;
  if (
    claims.iss !== expected.organization_id ||
    claims.sub !== expected.agent_id ||
    claims.jti !== expected.jti
  ) {
    throw new Error("recovered claims did not match expected_verified_claims");
  }
});

// vector_02: tampered artifact must be rejected
check("vector_02_tampered_artifact (verify-failure, digest mismatch)", () => {
  const vector = loadVector("vector_02_tampered_artifact.json");
  let threw = false;
  try {
    verifyArtifactProof(vector.signed_artifact, vector);
  } catch (exc) {
    threw = exc instanceof JwsVerificationError;
  }
  if (!threw) throw new Error("expected rejection, got acceptance");
});

// vector_03: wrong key must be rejected
check("vector_03_wrong_key (verify-failure, invalid signature)", () => {
  const vector = loadVector("vector_03_wrong_key.json");
  let threw = false;
  try {
    verifyArtifactProof(vector.signed_artifact, vector);
  } catch (exc) {
    threw = exc instanceof JwsVerificationError;
  }
  if (!threw) throw new Error("expected rejection, got acceptance");
});

// vector_04: integer/float digest equivalence
check("vector_04_integer_float_coercion (digest equivalence)", () => {
  const vector = loadVector("vector_04_integer_float_coercion.json");
  const intForm = canonicalize(vector.artifact_with_integer_version);
  if (intForm !== vector.expected_canonicalized_form_both) {
    throw new Error(`canonical form mismatch: ${intForm}`);
  }
  // Note: unlike the Python reference implementation, this harness's
  // canonicalize() has no separate "normalize float-with-zero-fraction
  // to int" step, because in JS there is no float/int distinction at
  // the JSON-number level to begin with -- JSON.parse("1.0") and
  // JSON.parse("1") both produce the identical JS number 1, and
  // Number->String always renders it as "1". The vector's
  // "artifact_with_float_version" variant is therefore not separately
  // exercised here; it is already proven equivalent by construction.
});

// vector_05: Unicode content
check("vector_05_unicode_content (verify-success, Unicode escaping)", () => {
  const vector = loadVector("vector_05_unicode_content.json");
  const artifact = vector.signed_artifact;
  const stripped = withoutProof(artifact);
  const canon = canonicalize(stripped);
  if (canon !== vector.expected_canonicalized_artifact_without_proof) {
    throw new Error(`canonical form mismatch:\n  got:      ${canon}\n  expected: ${vector.expected_canonicalized_artifact_without_proof}`);
  }
  if (canon.includes("café")) throw new Error("non-ASCII character was not escaped");
  if (!canon.includes("\\u00e9")) throw new Error("expected \\u00e9 escape for é");
  verifyArtifactProof(artifact, vector);
});

// vector_06: duplicate key must be rejected by strict parsing
check("vector_06_duplicate_key_rejected (strict parse failure)", () => {
  const vector = loadVector("vector_06_duplicate_key_rejected.json");
  const text = vector.raw_json_text;
  // A standard JSON.parse, like Python's bare json.loads, silently
  // keeps only the last occurrence -- demonstrating the ambiguity this
  // harness's own strict parser (below) must close instead of ignoring.
  const lenient = JSON.parse(text);
  if (lenient.version !== 2) throw new Error("expected lenient parse to keep the LAST duplicate");

  let rejected = false;
  try {
    strictJsonParse(text);
  } catch {
    rejected = true;
  }
  if (!rejected) throw new Error("expected strict parser to reject duplicate keys");
});

// JS has no built-in "reject duplicate keys" JSON option (unlike
// Python's object_pairs_hook), and JSON.parse's reviver callback runs
// AFTER duplicates have already been silently collapsed, so detecting
// them requires scanning the raw text before parsing. This is a
// conservative, depth-aware scan for TOP-LEVEL object keys only
// (sufficient for this harness's flat vector; a general-purpose
// implementation would recurse per nesting level the same way).
function countTopLevelKeyOccurrences(text, targetDepth = 1) {
  const counts = new Map();
  let depth = 0;
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (ch === "{" || ch === "[") depth += 1;
    else if (ch === "}" || ch === "]") depth -= 1;
    else if (ch === '"' && depth === targetDepth) {
      let j = i + 1;
      let key = "";
      while (text[j] !== '"') {
        key += text[j];
        j += 1;
      }
      let k = j + 1;
      while (/\s/.test(text[k])) k += 1;
      if (text[k] === ":") {
        counts.set(key, (counts.get(key) || 0) + 1);
      }
      i = j;
    }
    i += 1;
  }
  return counts;
}

function strictJsonParse(text) {
  const counts = countTopLevelKeyOccurrences(text);
  for (const [key, count] of counts) {
    if (count > 1) throw new Error(`Duplicate JSON key ${JSON.stringify(key)} is not permitted.`);
  }
  return JSON.parse(text);
}

if (failures > 0) {
  console.error(`\n${failures} vector(s) FAILED`);
  process.exit(1);
} else {
  console.log("\nAll vectors passed.");
}
